(() => {
const S=window.Store,E=S.esc,M=S.money,$=s=>document.querySelector(s),methods={online:'Online payment',cod:'Cash on delivery',koko:'Koko-style installments'};
const date=s=>new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const badge=s=>`<span class="status-pill">${E(s)}</span>`;
const error=(el,e)=>{el.textContent=e.message||String(e);el.setAttribute('role','alert');};
const totals=q=>`<div class="summary-line"><span>Items</span><strong>${M(q.subtotal)}</strong></div><div class="summary-line"><span>Delivery</span><strong>${M(q.shipping)}</strong></div><div class="summary-line total"><span>Total</span><strong>${M(q.total)}</strong></div>`;
const lines=o=>o.lines.map(i=>`<div class="checkout-item"><img src="${E(i.image)}" alt=""><div><strong>${E(i.name)}</strong><small>${E(i.option)} · Qty ${i.qty}</small><span>${M(i.price*i.qty)}</span></div></div>`).join('');
const plan=q=>S.installment(q.total).map((n,i)=>`<div><span>${['First payment','Second payment','Third payment'][i]}</span><strong>${M(n)}</strong><small>${['Today (simulated)','After 30 days (example)','After 60 days (example)'][i]}</small></div>`).join('');
let checkoutToken=S.uid('checkout'),pending=null;
function checkout(){const root=$('#commerce-checkout');if(!root)return;let q;try{q=S.quote(S.cart());}catch(e){root.innerHTML=`<div><h2>Let’s check your bag.</h2><p>${E(e.message)}</p><a class="button" href="bag.html">Return to bag</a></div>`;return;}
root.innerHTML=`<form id="order-form"><div class="checkout-step"><span>01</span><h2>Delivery details</h2><button type="button" class="outline" id="fill-sample">Use sample customer</button></div><p class="sample-note">Use fictional details. This demo stores order information only in this browser.</p><div class="form-grid"><label>Full name<input name="name" required maxlength="80" autocomplete="off" placeholder="Amaya Silva"></label><label>Email<input name="email" type="email" required maxlength="120" autocomplete="off" placeholder="amaya@example.com"></label><label class="full">Address<input name="address" required maxlength="250" autocomplete="off" placeholder="12 Example Lane"></label><label class="full">City<input name="city" required maxlength="80" autocomplete="off" placeholder="Colombo"></label></div><fieldset><legend>Delivery option</legend><label class="delivery-choice"><input type="radio" name="shipping" value="standard" checked><span>Standard delivery<small>Sample delivery fee ${M(350)}</small></span></label><label class="delivery-choice"><input type="radio" name="shipping" value="collection"><span>Boutique collection<small>No delivery fee · Demo option</small></span></label></fieldset><div class="checkout-step"><span>02</span><h2>How would you like to pay?</h2></div><fieldset class="payment-options"><legend class="sr-only">Payment method</legend><label class="payment-choice"><input type="radio" name="method" value="online" checked><span><strong>Online payment</strong><small>Simulated card gateway · No card details needed</small></span><b>CARD</b></label><label class="payment-choice"><input type="radio" name="method" value="cod"><span><strong>Cash on delivery</strong><small>Create an order with payment due on delivery</small></span><b>COD</b></label><label class="payment-choice"><input type="radio" name="method" value="koko"><span><strong>Koko-style installments</strong><small>Example three-part payment plan · Mock only</small></span><b class="koko-label">koko</b></label></fieldset><div id="installment-preview" hidden><h3>Your example payment plan</h3><div class="installments">${plan(q)}</div><p class="sample-note">Illustrative amounts and timing only. No connection to Koko, credit application, or real installment agreement.</p></div><p id="checkout-error" class="error-text" role="alert"></p><button class="button" id="place-order" type="submit">Continue to mock gateway</button><p class="sample-note">No money is collected. This creates a demo order visible in My orders and Demo admin.</p></form><aside class="order-summary"><h2>Your selection</h2><div id="checkout-lines">${lines(q)}</div><div id="checkout-totals">${totals(q)}</div><a class="text-link" href="bag.html">Edit your bag</a></aside>`;
const form=$('#order-form');$('#fill-sample').onclick=()=>{for(const [k,v] of Object.entries({name:'Amaya Silva',email:'amaya@example.com',address:'12 Example Lane',city:'Colombo'}))form.elements[k].value=v;};
form.onchange=()=>{try{const value=S.quote(S.cart(),form.elements.shipping.value);$('#checkout-totals').innerHTML=totals(value);$('#installment-preview .installments').innerHTML=plan(value);$('#installment-preview').hidden=form.elements.method.value!=='koko';$('#place-order').textContent=form.elements.method.value==='cod'?'Place demo COD order':'Continue to mock gateway';$('#checkout-error').textContent='';}catch(e){error($('#checkout-error'),e);}};
form.onsubmit=e=>{e.preventDefault();$('#checkout-error').textContent='';try{const data=Object.fromEntries(new FormData(form));pending={items:S.cart(),delivery:data.shipping,method:data.method,customer:{name:data.name,email:data.email,address:data.address,city:data.city},token:checkoutToken};const quote=S.quote(pending.items,pending.delivery);pending.expectedTotal=quote.total;if(data.method==='cod')finish();else gateway(quote);}catch(e){error($('#checkout-error'),e);}};
}
function finish(){const b=$('#place-order');if(b)b.disabled=true;try{const q=S.quote(pending.items,pending.delivery);if(q.total!==pending.expectedTotal)throw Error('Prices changed during checkout. Close the gateway and review your updated total.');const o=S.place(pending);pending=null;location.href='orders.html?order='+encodeURIComponent(o.id);}catch(e){const dialog=$('#payment-modal');if(dialog?.open)dialog.close();error($('#checkout-error'),e);if(b)b.disabled=false;}}
function gateway(q){const d=$('#payment-modal'),k=pending.method==='koko';d.innerHTML=`<div class="gateway"><p class="eyebrow">ROMANZ · PAYMENT SIMULATOR</p><h2 id="gateway-title">${k?'Koko-style payment plan':'Online payment gateway'}</h2><p class="gateway-total">${M(q.total)}</p><p>${k?'Preview an example three-part plan.':'Demo card · 4242 · Fixed test instrument'}</p>${k?`<div class="installments">${plan(q)}</div>`:''}<div class="demo-notice">Simulation only. Do not enter card numbers, passwords, or OTPs. Nothing is sent to a payment provider.</div><p class="sample-note">Choose an outcome to test the checkout.</p><div class="gateway-actions"><button class="button" id="approve-payment">${k?'Simulate plan approval':'Simulate successful payment'}</button><button class="outline" id="decline-payment">Simulate decline</button><button class="text-button" id="cancel-payment">Cancel payment</button></div></div>`;d.showModal();$('#approve-payment').onclick=()=>{ $('#approve-payment').disabled=true;finish();};const exit=outcome=>{try{S.attempt(pending.method,outcome,q.total,pending.token);d.close();$('#checkout-error').textContent=outcome==='Declined (mock)'?'Demo payment declined. Your bag is unchanged. Try again or select a different payment method.':'Payment cancelled. Your bag is unchanged.';}catch(e){error($('#checkout-error'),e);d.close();}};$('#decline-payment').onclick=()=>exit('Declined (mock)');$('#cancel-payment').onclick=()=>exit('Cancelled');d.oncancel=e=>{e.preventDefault();exit('Cancelled');};}
function orders(){const root=$('#customer-orders');if(!root)return;const list=S.load().orders.filter(o=>o.source==='checkout');const selected=new URLSearchParams(location.search).get('order');if(!list.length){root.innerHTML='<div class="empty-bag"><h2>Your story starts here.</h2><p>No demo orders yet. Add a piece to your bag and try checkout.</p><a class="button" href="collection.html">Explore jewellery</a></div>';return;}root.innerHTML=list.map(o=>`<article class="customer-order ${o.id===selected?'highlight-order':''}"><div class="order-heading"><div><p class="eyebrow">${o.id===selected?'DEMO ORDER RECEIVED':'ROMANZ ORDER'}</p><h2>${E(o.id)}</h2><p>${date(o.date)} · ${E(o.customer.name)}</p></div><div>${badge(o.status)} ${badge(o.payment)}</div></div><div class="customer-order-grid"><div>${lines(o)}</div><div><h3>Order details</h3><p>${E(methods[o.method])}<br>${o.delivery==='collection'?'Boutique collection':'Standard delivery'}<br>${E(o.customer.address)}, ${E(o.customer.city)}</p>${totals(o)}${o.installments?`<p class="sample-note">Example installments: ${o.installments.map(M).join(' + ')}. This is not a real payment agreement.</p>`:''}<p class="sample-note">Demo order only · No payment or delivery will occur.</p></div></div></article>`).join('');}
let section='overview',orderSearch='',orderFilter='all';
function admin(){if(!$('#admin-content'))return;document.querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>{section=b.dataset.admin;renderAdmin();});$('#seed-orders').onclick=()=>{try{S.seed();$('#admin-message').textContent='Three fictional example orders added. Example orders do not reduce stock.';renderAdmin();}catch(e){error($('#admin-message'),e);}};renderAdmin();}
function metrics(s){const live=s.orders.filter(o=>o.status!=='Cancelled');return `<div class="metric-grid"><article><span>Demo order value</span><strong>${M(live.reduce((n,o)=>n+o.total,0))}</strong><small>Simulated, not real revenue</small></article><article><span>Orders</span><strong>${s.orders.length}</strong><small>${s.orders.filter(o=>o.status==='Processing').length} processing</small></article><article><span>Active products</span><strong>${s.products.filter(p=>p.active).length}</strong><small>${s.products.filter(p=>p.active&&p.stock<5).length} with low stock</small></article><article><span>COD outstanding</span><strong>${M(s.orders.filter(o=>o.payment==='Due on delivery').reduce((n,o)=>n+o.total,0))}</strong><small>Demo cash awaiting collection</small></article></div>`;}
function orderTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Payment</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>${E(o.id)}</strong><small>${date(o.date)} ${o.source==='seed'?'· Example':''}</small></td><td>${E(o.customer.name)}</td><td>${E(methods[o.method])}<small>${E(o.payment)}</small></td><td>${M(o.total)}</td><td>${badge(o.status)}</td><td><button class="outline small" data-order="${E(o.id)}">Manage</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty"><h3>No orders here yet</h3><p>Complete a demo checkout or load example orders to explore the dashboard.</p><a class="text-link" href="collection.html">Open storefront</a></div>';}
function renderAdmin(){const s=S.load(),root=$('#admin-content');$('#admin-title').textContent={overview:'Overview',orders:'Orders',products:'Products & stock',payments:'Payments'}[section];document.querySelectorAll('[data-admin]').forEach(b=>{b.classList.toggle('selected',b.dataset.admin===section);b.setAttribute('aria-pressed',String(b.dataset.admin===section));});if(section==='overview')root.innerHTML=metrics(s)+`<div class="panel-heading"><h2>Recent orders</h2><span>All activity is simulated</span></div>`+orderTable(s.orders.slice(0,6))+`<div class="admin-callouts"><article><h3>One connected demo</h3><p>Place a customer order, then manage its status here. Product prices and stock are shared with this browser’s storefront.</p></article><article><h3>Try each payment path</h3><p>Online approval or decline, COD with cash due, and a Koko-style installment preview. No actual gateway is connected.</p></article></div>`;
if(section==='orders'){root.innerHTML=`<div class="admin-filters"><label>Search orders<input id="order-search" type="search" placeholder="Order ID or customer" value="${E(orderSearch)}"></label><label>Status<select id="order-filter">${['all','Processing','Shipped','Delivered','Cancelled'].map(v=>`<option ${v===orderFilter?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="admin-orders-table"></div>`;const refresh=()=>{const list=S.load().orders.filter(o=>(orderFilter==='all'||o.status===orderFilter)&&`${o.id} ${o.customer.name}`.toLowerCase().includes(orderSearch.toLowerCase()));$('#admin-orders-table').innerHTML=orderTable(list);};$('#order-search').oninput=e=>{orderSearch=e.target.value;refresh();};$('#order-filter').onchange=e=>{orderFilter=e.target.value;refresh();};refresh();}
if(section==='products')root.innerHTML=`<div class="panel-heading"><p>${s.products.length} products · Edits appear in the storefront on refresh</p><button class="button" id="new-product">Add sample product</button></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Visibility</th><th></th></tr></thead><tbody>${s.products.map(p=>`<tr><td><div class="admin-product"><img src="${E(p.image)}" alt=""><span>${E(p.name)}</span></div></td><td>${E(p.category)}</td><td>${M(p.price)}</td><td>${p.stock}${p.stock<5?' · Low':''}</td><td>${p.active?'Visible':'Hidden'}</td><td><button class="outline small" data-product="${E(p.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`;
if(section==='payments')root.innerHTML=`<div class="demo-notice">Payment activity is simulated. No card details, OTPs, or provider credentials are stored. COD collection is updated from the order manager.</div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Method</th><th>Outcome</th><th>Amount</th><th>Order</th></tr></thead><tbody>${s.transactions.map(t=>`<tr><td>${E(t.id)}<small>${date(t.date)}</small></td><td>${E(methods[t.method])}</td><td>${badge(t.outcome)}</td><td>${M(t.total)}</td><td>${E(t.orderId||'No order created')}</td></tr>`).join('')||'<tr><td colspan="5">No payment activity yet. Try a demo checkout.</td></tr>'}</tbody></table></div>`;
$('#new-product')?.addEventListener('click',()=>editProduct());
}
function manageOrder(id){const o=S.load().orders.find(o=>o.id===id);if(!o)return;const d=$('#admin-dialog');d.innerHTML=`<div class="admin-modal"><button class="close" data-close aria-label="Close order manager">×</button><p class="eyebrow">DEMO ORDER MANAGER</p><h2 id="admin-dialog-title">${E(o.id)}</h2><p>${E(o.customer.name)} · ${E(o.customer.email)}</p><p>${E(o.customer.address)}, ${E(o.customer.city)}</p>${lines(o)}${totals(o)}<p>${E(methods[o.method])} · ${E(o.payment)}</p><form id="status-form"><label>Order status<select name="status">${['Processing','Shipped','Delivered','Cancelled'].map(v=>`<option ${v===o.status?'selected':''}>${v}</option>`).join('')}</select></label>${o.method==='cod'?'<label class="check-label"><input type="checkbox" name="collected"> Mark cash collected (delivered orders only)</label>':''}<p class="sample-note">Cancelling restores reserved stock once. Paid orders receive a simulated refund status. No money moves.</p><p id="modal-error" class="error-text" role="alert"></p><button class="button">Save order status</button></form></div>`;d.showModal();$('#status-form').onsubmit=e=>{e.preventDefault();try{S.updateOrder(id,e.target.elements.status.value,!!e.target.elements.collected?.checked);d.close();$('#admin-message').textContent='Order updated. The change is visible in My orders.';renderAdmin();}catch(ex){error($('#modal-error'),ex);}};}
function editProduct(id){const p=S.load().products.find(p=>p.id===id),d=$('#admin-dialog');d.innerHTML=`<div class="admin-modal"><button class="close" data-close aria-label="Close product editor">×</button><p class="eyebrow">CATALOGUE EDITOR</p><h2 id="admin-dialog-title">${p?'Edit product':'Add sample product'}</h2><form id="product-form" class="form-grid"><label class="full">Product name<input name="name" required maxlength="70" value="${E(p?.name||'')}"></label><label>Price (LKR)<input name="price" type="number" min="100" max="1000000" step="1" required value="${p?.price||4900}"></label><label>Stock<input name="stock" type="number" min="0" max="999" step="1" required value="${p?.stock??12}"></label><label>Category<select name="category" ${p?'disabled':''}>${['rings','earrings','necklaces','bracelets','sets'].map(v=>`<option ${v===p?.category?'selected':''}>${v}</option>`).join('')}</select></label><label>Sample photograph<select name="image" ${p?'disabled':''}>${S.defaults.slice(0,9).map(x=>`<option value="${E(x.image)}" ${x.image===p?.image?'selected':''}>${E(x.name)}</option>`).join('')}</select></label><label class="check-label full"><input name="active" type="checkbox" ${!p||p.active?'checked':''}> Visible in storefront</label><p id="modal-error" class="error-text full" role="alert"></p><button class="button full">Save product</button></form></div>`;d.showModal();$('#product-form').onsubmit=e=>{e.preventDefault();try{const f=e.target.elements;S.product({id:p?.id,name:f.name.value,price:Number(f.price.value),stock:Number(f.stock.value),active:f.active.checked,category:f.category.value,image:f.image.value});d.close();$('#admin-message').textContent='Product saved. Refresh the storefront to see the change.';renderAdmin();}catch(ex){error($('#modal-error'),ex);}};}
document.addEventListener('click',e=>{const order=e.target.closest('[data-order]'),product=e.target.closest('[data-product]');if(order)manageOrder(order.dataset.order);if(product)editProduct(product.dataset.product);if(e.target.closest('[data-close]'))$('#admin-dialog').close();});
checkout();orders();admin();
})();
